<script setup lang="ts">
import {appUrl} from '../lib/urls';
import {ref} from 'vue';import {Head,useForm} from '@inertiajs/vue3';import {ArrowRight,Sparkles,ShieldCheck,LoaderCircle,ArrowUpRight} from 'lucide-vue-next';
defineProps<{canRegister:boolean;openaiConfigured:boolean}>();const register=ref(false);const form=useForm({name:'',email:'',password:'',password_confirmation:'',remember:true});function submit(){form.post(appUrl(register.value?'/register':'/login'),{onFinish:()=>form.reset('password','password_confirmation')});}
</script>
<template><Head title="Entrar"/><div class="auth-layout"><aside class="auth-story"><a class="brand" :href="appUrl('/')"><img class="brand-logo" :src="appUrl('/brand/g-analise-icon.png')" alt=""><span class="brand-wordmark"><span class="brand-product">G-Analise <span class="brand-ai">IA</span></span><small>UM PRODUTO INOVADORA</small></span></a><div><span class="welcome-eyebrow"><Sparkles :size="16"/> SEU PRÓXIMO DASHBOARD COMEÇA AQUI</span><h1>Boas perguntas.<br>Grandes decisões.</h1><p>Um espaço para transformar suas ideias em dashboards, com inteligência artificial e todo o poder do G-Analise BI.</p><div class="auth-visual"><div><span>RECEITA EM FOCO</span><strong>Uma nova perspectiva.</strong><div class="auth-bars"><i v-for="h in [30,45,37,62,55,74,66,83,73,96]" :key="h" :style="{height:h+'%'}"></i></div></div></div></div><footer><ShieldCheck :size="15"/> Seus acessos. Suas permissões. Seu controle.</footer></aside><main class="auth-form-panel"><div><span class="section-eyebrow">BEM-VINDO AO SEU WORKSPACE</span><h1>{{register?'Crie sua conta':'Vamos continuar?'}}</h1><p>{{register?'Prepare seu espaço para criar com inteligência.':'Entre para acessar seus projetos e conversas.'}}</p><a v-if="openaiConfigured" :href="appUrl('/auth/openai')" class="provider-connect auth-openai"><Sparkles :size="19"/> Continuar com ChatGPT<ArrowUpRight :size="15"/></a><div v-if="openaiConfigured" class="auth-divider">ou entre com seu e-mail</div><form @submit.prevent="submit"><label v-if="register">Nome<input v-model="form.name" required autocomplete="name"></label><label>E-mail<input v-model="form.email" type="email" required autocomplete="username" placeholder="voce@empresa.com.br"></label><label>Senha<input v-model="form.password" type="password" required :autocomplete="register?'new-password':'current-password'" :minlength="register?12:undefined"></label><label v-if="register">Confirme a senha<input v-model="form.password_confirmation" type="password" required autocomplete="new-password"></label><div v-if="Object.keys(form.errors).length" class="form-error" role="alert">{{Object.values(form.errors)[0]}}</div><button class="primary-button full-width auth-submit" :disabled="form.processing"><LoaderCircle v-if="form.processing" :size="18" class="spin"/>{{register?'Criar conta':'Entrar no workspace'}}<ArrowRight :size="17"/></button></form><p v-if="canRegister" class="auth-register">{{register?'Já tem uma conta?':'Primeiro acesso?'}} <button @click="register=!register;form.clearErrors()">{{register?'Entrar':'Criar conta'}}</button></p><p v-else class="auth-note">Seu acesso é disponibilizado pelo administrador da instalação.</p><small class="auth-privacy">G-Analise IA é um produto Inovadora integrado ao G-Analise BI.</small></div></main></div></template>
